static void printTriangle(int n) {
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= i; j++) {
            System.out.print("*");
        }
        System.out.println();
    }
}

public List<String> fizzBuzz(int n) {
    List<String> list = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        if (i % 15 == 0) {
            list.add("FizzBuzz");
        } else if (i % 3 == 0) {
            list.add("Fizz");
        } else if (i % 5 == 0) {
            list.add("Buzz");
        } else {
            list.add(Integer.toString(i));
        }
    }
    return list;
}

static int sumOfDigits(int n) {
    int sum = 0;
    int q = Math.abs(n);
    while(q>0){
        int p = q%10;
        sum +=p;
        q=q/10;
    }
    return sum;
}
